#[cfg(test)]mod captured_closed_scope_contract{
 use super::*;
 fn fixture()->(IdTable<ExprId,Expr>,IdTable<LevelId,Level>,Environment){
  let mut e=IdTable::default();let mut l=IdTable::default();l.insert(LevelId(0),Level::Zero).unwrap();
  for(id,x)in[(0,Expr::Sort(LevelId(0))),(1,Expr::Const{name:NameId(1),levels:vec![]}),(2,Expr::Pi{domain:ExprId(1),body:ExprId(1)}),(3,Expr::Const{name:NameId(2),levels:vec![]}),(4,Expr::Const{name:NameId(3),levels:vec![]}),(5,Expr::BVar(0)),(6,Expr::Const{name:NameId(4),levels:vec![]}),(7,Expr::BVar(1)),(8,Expr::App{fun:ExprId(7),arg:ExprId(5)})]{e.insert(ExprId(id),x).unwrap();}
  let env=Environment::empty().extend(NameId(1),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap().extend(NameId(2),crate::environment::ConstantDecl::axiom(vec![],ExprId(2))).unwrap().extend(NameId(3),crate::environment::ConstantDecl::axiom(vec![],ExprId(1))).unwrap().extend(NameId(4),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap();(e,l,env)
 }
 fn closed(c:&TypeChecker<'_>)->Closure{c.closure(ExprId(8),EnvFrame::empty().extend(c.closure(ExprId(3),EnvFrame::empty())).extend(c.closure(ExprId(4),EnvFrame::empty())))}
 #[test]fn closed_captured_source_and_term_type_replay_across_changed_unrelated_domain(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=closed(&c);let old=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];let new=[TypeValue::Term(c.closure(ExprId(6),EnvFrame::empty()))];let first=c.infer_exact_closure_in_context(&t,&old,&mut 4096,0);assert!(matches!(first,Some(TypeValue::Term(_))));let mut one=1;assert_eq!(c.infer_exact_closure_in_context(&t,&new,&mut one,0),first,"captured-closed-context-change");assert_eq!(one,0);}
 #[test]fn completed_closed_pair_can_be_replayed_under_empty_context(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=closed(&c);let old=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];let first=c.infer_exact_closure_in_context(&t,&old,&mut 4096,0);assert!(first.is_some());assert_eq!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0),first,"captured-closed-empty-context");}
 #[test]fn open_captured_argument_never_inherits_closed_scope_replay(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=c.closure(ExprId(8),EnvFrame::empty().extend(c.closure(ExprId(3),EnvFrame::empty())).extend_free(FreeId(0)));let old=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];let new=[TypeValue::Term(c.closure(ExprId(6),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&old,&mut 4096,0).is_some());assert!(c.infer_exact_closure_in_context(&t,&new,&mut 1,0).is_none());}
 #[test]fn closed_pair_still_requires_source_epoch_scope_and_paid_root(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let mut c=TypeChecker::new(&e,&l,&env);let t=closed(&c);let old=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&old,&mut 4096,0).is_some());assert!(c.infer_exact_closure_in_context(&t,&[],&mut 0,0).is_none());assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,48).is_none());c.binding_revocation_epoch.set(Some(1));assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());c.binding_revocation_epoch.set(Some(0));c.strict_origin_probe=true;assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());c.strict_origin_probe=false;c.inherited_binding_lineage=Some(InheritedBindings{ledger:c.checked_binding_lineage.clone(),epoch:c.binding_revocation_epoch.clone(),captured_epoch:Some(0)});assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());c.inherited_binding_lineage=None;let other=closed(&c);assert!(c.infer_exact_closure_in_context(&other,&[],&mut 1,0).is_none());}
}
